import * as am5 from '@amcharts/amcharts5';
import * as am5xy from '@amcharts/amcharts5/xy';
import { IAxisRange } from '../BarChart';
import { ICombinedTooltipHtmlConfig, ICustomziedTooltipHtmlConfig, IExportPluginConfig } from '../utilities/interface';
export interface IChartConfig {
    /**
     * Key of the line chart to pick the values.
     */
    value: string;
    /**
     * Label of the chart being plot. To be used as lable of the ledgend below the chart.
     */
    label: string;
    /**
     * type of the line in line chart.
     */
    type?: string;
    /**
     * color of the line in line chart.
     */
    color?: string;
}
export interface INumberFormatterConfig {
    /**
     * Format which is used to format the number
     */
    numberFormat: string;
    /**
     * Add prefix/suffix to the number
     */
    bigNumberPrefixes?: {
        number: number;
        suffix: string;
    }[];
}
export interface LineSeriesSettings {
    tooltipSettings: am5.ITooltipSettings;
}
export interface ILineCombinedTooltipHtmlConfig extends ICombinedTooltipHtmlConfig {
}
export interface ILineCustomziedTooltipHtmlConfig extends ICustomziedTooltipHtmlConfig {
}
export interface ILineExportingSettings extends IExportPluginConfig {
}
export interface ILineChart {
    /**
     * Unique Id to Line Chart
     */
    chartId: string;
    /**
     * Input data field for X value.
     */
    valueXAxis: string;
    /**
     * Data to render Line Chart
     */
    data: any;
    /**
     * Config to the chart
     */
    chartConfig: IChartConfig[];
    /**
     * Config used to format the number in chart.
     */
    numberFormatterConfig?: INumberFormatterConfig;
    /**
     * Weight of the graph and its container in Chart.
     * Default value will 100%.
     */
    chartWidth?: string;
    /**
     * Height of the graph and its container in Chart.
     * Default value will 348px.
     */
    chartHeight?: string;
    /**
     * Tooltip of the Chart.
     * Default it will be true.
     */
    /**
     *  bar chart settings
     */
    chartSettings?: am5xy.IXYChartSettings;
    isTooltip?: boolean;
    /**
     * Color Scheme of the Chart.
     * Default it will be MONOCHROME_COLORS.
     */
    colorScheme?: 'mono' | 'color' | 'custom';
    /**
     * Number Format of the Chart.
     * Default it will be string.
     */
    numberFormat?: string;
    /**
     *  Multiple configurations for the chart series object
     *  Check series reference for various config options.
     *
     *  @see {@link https://www.amcharts.com/docs/v5/charts/xy-chart/series/} for more info.
     */
    seriesSettings?: LineSeriesSettings;
    /**
     *  Axis range object settings. See am5 documentation for more details.
     *
     *  @see {@link https://www.amcharts.com/docs/v4/concepts/axes/axis-ranges/#Range_labels} for more info.
     */
    axisRange?: IAxisRange[];
    /**
     * configure grid line visibility
     *
     */
    gridLineVisibility?: {
        horizontal?: boolean;
        vertical: boolean;
    };
    /**
     * Combined tooltip html configuration
     */
    combinedToolTipHtmlConfig?: ILineCombinedTooltipHtmlConfig;
    /**
     * Customized tooltip html configuration
     */
    customziedTooltipHtmlConfig?: ILineCustomziedTooltipHtmlConfig;
    /**
     * config for export plugin integration
     */
    exportPluginConfig?: ILineExportingSettings;
}
